def icon(name, size=40, color="currentColor", width=2.2, cls="ico"):
    return (
        f'<svg class="{cls}" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" '
        f'stroke="{color}" stroke-width="{width}" stroke-linecap="round" stroke-linejoin="round">{P[name]}</svg>'
    )
